// An entry in the kubemoot_scheduler_performance bucket: one agent's recent model
// requests and capacity waits for one model on one server, which the scheduler
// learns from. Key: <server>.<model>.<agent>, each token escaped. Times are
// milliseconds; an engine timing the engine did not report is -1.
type SchedulerPerformance struct {
	// The ModelServer.
	Server string `json:"server"`

	// The model.
	Model string `json:"model"`

	// The agent that wrote the entry, as <namespace>/<agent>.
	Agent string `json:"agent"`

	// When the entry was last written, epoch milliseconds.
	UpdatedAt int64 `json:"updatedAt,omitempty"`

	// Requests this agent has recorded for the model on the server.
	Requests int64 `json:"requests,omitempty"`

	// How many of those requests failed or timed out.
	Failures int64 `json:"failures,omitempty"`

	// The most recent requests, oldest first.
	Samples []SchedulerPerformanceSamplesElem `json:"samples"`

	// The most recent waits for capacity that ended with a call placed here, oldest
	// first.
	Waits []SchedulerPerformanceWaitsElem `json:"waits"`
}

type SchedulerPerformanceSamplesElem struct {
	// Calls holding a ticket on the server when the request started, this one
	// included.
	ActiveCalls int64 `json:"activeCalls,omitempty"`

	// When the request started, epoch milliseconds.
	At int64 `json:"at"`

	// The model was not resident on the server when the call was placed.
	ColdStart bool `json:"coldStart,omitempty"`

	// Time from sending the request to the reply or failure, measured by the agent.
	DurationMs int64 `json:"durationMs"`

	// Generation time the engine reported; -1 when not reported.
	EvalMs int64 `json:"evalMs,omitempty"`

	// tool-turn: one model turn of the tool loop. simple: a no-tool call (advisory,
	// synthesis). triage: a triage call. calibration: a probe the scheduler sent to
	// measure the server, not a crew call.
	Kind SchedulerPerformanceSamplesElemKind `json:"kind"`

	// Model load time the engine reported; -1 when not reported.
	LoadMs int64 `json:"loadMs,omitempty"`

	// False when the request failed or timed out.
	Ok bool `json:"ok"`

	// Generated tokens the engine reported; 0 when unknown.
	OutputTokens int64 `json:"outputTokens,omitempty"`

	// Prompt processing time the engine reported; -1 when not reported.
	PromptEvalMs int64 `json:"promptEvalMs,omitempty"`

	// Prompt tokens the engine reported; 0 when unknown.
	PromptTokens int64 `json:"promptTokens,omitempty"`
}

type SchedulerPerformanceSamplesElemKind string

const SchedulerPerformanceSamplesElemKindCalibration SchedulerPerformanceSamplesElemKind = "calibration"
const SchedulerPerformanceSamplesElemKindSimple SchedulerPerformanceSamplesElemKind = "simple"
